module asyn_fifo #(
    parameter DEPTH = 16,
    parameter WIDTH = 8,
    parameter ADDR_WIDTH = $clog2(DEPTH)
) (
    input 					wclk,
    input 					rclk,
    input 					wrstn,
    input					rrstn,
    input 					winc,
    input 			 		rinc,
    input 		[WIDTH-1:0]	wdata,
    output wire				wfull,
    output wire				rempty,
    output wire [WIDTH-1:0]	rdata
);


wire wen, ren;
reg [3:0] waddr_bin, raddr_bin;
reg [3:0] wptr, rptr, wptr_buff, wptr_syn, rptr_buff, rptr_syn;

assign wen = winc & ~wfull;
assign ren = rinc & ~rempty;

dual_port_RAM #(.DEPTH(DEPTH), .WIDTH(WIDTH)) ram(
.wclk(wclk),
.rclk(rclk),
.wenc(wen),
.renc(ren),
.waddr(waddr_bin),
.raddr(raddr_bin),
.wdata(wdata),
.rdata(rdata)
);

always @(posedge wclk or negedge wrstn) begin
	if(!wrstn) begin
		waddr_bin <= 0;
	end else begin
		if(winc && !wfull) begin
			waddr_bin <= waddr_bin + 1;
		end
	end
end
always @(posedge wclk or negedge wrstn) begin
	if(!wrstn) begin
		wptr <= 0;
	end else begin
		wptr <= {wptr[3], wptr[3:1]} ^ wptr;
	end
end
always @(posedge wclk or negedge wrstn) begin
	if(!wrstn) begin
		wptr_buff <= 0;
	end else begin
		wptr_buff <= wptr;
	end
end

always @(posedge wclk or negedge wrstn) begin
	if(!wrstn) begin
		rptr_syn <= 0;
	end else begin
		rptr_syn <= rptr_syn ^ rptr;
	end
end

always @(posedge rclk or negedge rrstn) begin
	if(!rrstn) begin
		raddr_bin <= 0;
	end else begin
		if(rinc && !rempty) begin
			raddr_bin <= raddr_bin + 1;
		end
	end
end
always @(posedge rclk or negedge rrstn) begin
	if(!rrstn) begin
		rptr <= 0;
	end else begin
		rptr <= {rptr[3], rptr[3:1]} ^ rptr;
	end
end
always @(posedge rclk or negedge rrstn) begin
	if(!rrstn) begin
		rptr_buff <= 0;
	end else begin
		rptr_buff <= rptr;
	end
end

assign wfull = (wptr == {~rptr_syn[3:3], rptr_syn[2:0]});
assign rempty = (rptr == wptr_syn);
endmodule

module dual_port_RAM #(parameter DEPTH = 16,  parameter WIDTH = 8)
(
	 input wclk	,
	 input wenc	,
	 input [$clog2(DEPTH)-1:0] waddr  ,
	 input [WIDTH-1:0] wdata ,
	 input rclk	,
	 input renc	,
	 input [$clog2(DEPTH)-1:0] raddr ,
	 output reg [WIDTH-1:0] rdata 		
);

reg [WIDTH-1:0] RAM_MEM [0:DEPTH-1];

always @(posedge wclk) begin
	if(wenc)
		RAM_MEM[waddr] <= wdata;
end 

always @(posedge rclk) begin
	if(renc)
		rdata <= RAM_MEM[raddr];
end 

endmodule
